INSERT INTO imoveis (ref, slug, status, publico, privado, ordem) VALUES ('GG-0142', 'apartamento-frente-mar-gonzaga-santos', 'Disponível', '{"slug":"apartamento-frente-mar-gonzaga-santos","ref":"GG-0142","titulo":"Apartamento frente mar no Gonzaga","tipo":"Apartamento","finalidade":"venda","cidade":"Santos","bairro":"Gonzaga","preco":1350000,"condominio":1650,"iptu":420,"area":128,"dormitorios":3,"suites":1,"banheiros":3,"vagas":2,"distanciaPraia":40,"vistaMar":true,"destaque":true,"resumo":"Andar alto, sala ampla com sacada voltada para a orla e o jardim da praia.","descricao":["Apartamento em andar alto, de frente para o jardim da orla do Gonzaga. A sala em dois ambientes se abre para uma sacada com vista direta para o mar e recebe sol da manhã.","São três dormitórios, sendo uma suíte com closet, cozinha planejada, área de serviço independente e dependência completa. O prédio tem portaria 24 horas e duas vagas demarcadas.","A localização permite fazer quase tudo a pé: praia, comércio da Ana Costa, restaurantes, bancos e o canal 3 a poucos minutos."],"caracteristicas":["Vista mar","Sacada","Suíte com closet","Cozinha planejada","Dependência completa","Sol da manhã","Portaria 24h","Andar alto"],"lazer":["Salão de festas","Academia","Bicicletário"],"imagens":["/fotos/sala-vista-mar.jpg","/fotos/suite.jpg","/fotos/cozinha.jpg","/fotos/santos.jpg"]}', '{"endereco":"Av. Presidente Wilson, 1250","complemento":"Apto 141","cep":"11065-200","proprietario":"Maria Aparecida Souza","telefone":"(13) 90000-0101","email":"maria.souza@example.com","chaves":"Com o corretor","chavesObs":"","comissao":"6%","exclusividade":true,"exclusividadeAte":"2027-03-06","captadoEm":"2026-09-27","observacoes":"Aceita proposta a partir de R$ 1,3 milhão. Visitas somente à tarde."}', 0);
